import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Verify a desktop installation","description":"","frontmatter":{},"headers":[],"relativePath":"real-hardware-verification.md","filePath":"real-hardware-verification.md"}'),n={name:"real-hardware-verification.md"};function o(r,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="verify-a-desktop-installation" tabindex="-1">Verify a desktop installation <a class="header-anchor" href="#verify-a-desktop-installation" aria-label="Permalink to &quot;Verify a desktop installation&quot;">​</a></h1><p>For contributors and package maintainers: use this checklist to verify a release on a real desktop. It covers login, input and visible behaviour that headless tests cannot prove. Ordinary installation ends with the steps in the <a href="./installation">install guide</a>.</p><h2 id="_1-log-in" tabindex="-1">1. Log in <a class="header-anchor" href="#_1-log-in" aria-label="Permalink to &quot;1. Log in&quot;">​</a></h2><p>Use the <a href="./installation">package guide</a> or complete <a href="./install-source#3-add-a-login-session">source session registration</a>. Choose <strong>Gnoblin</strong> at the login screen.</p><p>Record the build you installed, distribution, GPU, displays and scale factors.</p><h2 id="_2-check-your-shell" tabindex="-1">2. Check your shell <a class="header-anchor" href="#_2-check-your-shell" aria-label="Permalink to &quot;2. Check your shell&quot;">​</a></h2><p>Verify the bar, dock, launcher and notifications appear and respond to input. Open and close menus near each screen edge. Test every display.</p><p>If the shell fails, confirm desktop right-click opens a terminal and the recovery panel appears. Check the shell&#39;s log before restarting it.</p><h2 id="_3-check-windows-and-keys" tabindex="-1">3. Check windows and keys <a class="header-anchor" href="#_3-check-windows-and-keys" aria-label="Permalink to &quot;3. Check windows and keys&quot;">​</a></h2><p>Test focus, typing, minimise/restore, maximise, fullscreen, drag and resize. Check app switching, launcher shortcuts and any custom bindings.</p><p>For SSD windows, check all buttons, titlebar drag and edge resize. A correct screenshot alone does not prove input works.</p><h2 id="_4-reload" tabindex="-1">4. Reload <a class="header-anchor" href="#_4-reload" aria-label="Permalink to &quot;4. Reload&quot;">​</a></h2><p>Change one visible config setting, then:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>Confirm the setting changed and existing windows survived. The second command also reloads theme and user scripts.</p><h2 id="_5-lock-and-unlock" tabindex="-1">5. Lock and unlock <a class="header-anchor" href="#_5-lock-and-unlock" aria-label="Permalink to &quot;5. Lock and unlock&quot;">​</a></h2><p>Confirm the lock screen receives input, desktop controls are unavailable while locked, and the shell recovers after unlock.</p><h2 id="_6-screen-sharing-and-remote-input" tabindex="-1">6. Screen sharing and remote input <a class="header-anchor" href="#_6-screen-sharing-and-remote-input" aria-label="Permalink to &quot;6. Screen sharing and remote input&quot;">​</a></h2><p>With the patched portal backend installed:</p><ol><li>Under the default policy, start a share and complete the source picker.</li><li>Confirm the selected monitor is the one actually shared.</li><li>Test an explicit <code>ask</code> rule, then a <code>deny</code> rule.</li><li>For an <code>allow</code> rule, test both permitted and broader device requests.</li><li>Stop sharing and confirm the stream ends.</li></ol><p>See <a href="/guides/permissions">portal permissions</a> for current permission policy.</p><h2 id="_7-return-to-gnome" tabindex="-1">7. Return to GNOME <a class="header-anchor" href="#_7-return-to-gnome" aria-label="Permalink to &quot;7. Return to GNOME&quot;">​</a></h2><p>Log out and select GNOME. Confirm its desktop still works. For package-release testing, also remove Gnoblin using its documented uninstall path and check that the Gnoblin login entry disappears.</p><p>Record failures separately from skipped checks. Include the exact commands, logs and visible outcome; a successful build is not a successful desktop test.</p>`,24)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
